import React from 'react';
import { PhotoProvider, PhotoView } from 'react-photo-view';
import './Gallery.css';

const Gallery = ({ language }) => {
  const publicUrl = process.env.PUBLIC_URL || '';
  const images = Array.from({ length: 36 }, (_, i) => `${publicUrl}/gallery/gallery-${i + 1}.webp`);

  return (
    <section className="gallery-section section animate-in">
      <div className="container">
        <h2 className="section-title">{language === 'RU' ? 'Галерея Тюмени' : 'Tyumen Gallery'}</h2>
        <p className="section-subtitle">
          {language === 'RU' ? 'Посмотрите, как выглядит город' : 'See how the city looks'}
        </p>
        
        {/* Обертка провайдера галереи */}
        <PhotoProvider speed={() => 300}>
          <div className="gallery-grid">
            {images.map((src, idx) => (
              <PhotoView key={idx} src={src}>
                <div className="gallery-item">
                  <img src={src} alt={`Тюмень ${idx + 1}`} loading="lazy" />
                </div>
              </PhotoView>
            ))}
          </div>
        </PhotoProvider>
      </div>
    </section>
  );
};

export default Gallery;